CREATE TABLE system_info (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), environment text NOT NULL CHECK(environment IN ('test','production')));
CREATE TABLE roles(code text PRIMARY KEY, name text NOT NULL);
CREATE TABLE permissions(code text PRIMARY KEY);
CREATE TABLE role_permissions(role_code text REFERENCES roles(code), permission_code text REFERENCES permissions(code), PRIMARY KEY(role_code,permission_code));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE CHECK(username=lower(username)), display_name text NOT NULL, password_hash text NOT NULL, role_code text NOT NULL REFERENCES roles(code), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), code text NOT NULL, name text NOT NULL, UNIQUE(project_id,code), UNIQUE(project_id,id));
CREATE TABLE warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), code text NOT NULL, name text NOT NULL, UNIQUE(project_id,code), UNIQUE(project_id,id));
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, warehouse_id uuid NOT NULL, code text NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(project_id,warehouse_id) REFERENCES warehouses(project_id,id), UNIQUE(project_id,code), UNIQUE(project_id,id));
CREATE TABLE batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), code text NOT NULL, UNIQUE(project_id,code), UNIQUE(project_id,id));
CREATE TABLE user_scopes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), project_id uuid NOT NULL REFERENCES projects(id), warehouse_id uuid, customer_id uuid, FOREIGN KEY(project_id,warehouse_id) REFERENCES warehouses(project_id,id), FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id));
CREATE TABLE bundles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bundle_no text NOT NULL UNIQUE CHECK(bundle_no=upper(trim(bundle_no)) AND length(bundle_no)>0), project_id uuid NOT NULL REFERENCES projects(id), batch_id uuid NOT NULL, location_id uuid NOT NULL, customer_id uuid NOT NULL, reserved_for_customer_id uuid, net_weight numeric(14,6) NOT NULL CHECK(net_weight>0 AND net_weight<100000000), physical_status text NOT NULL CHECK(physical_status IN ('IN_STOCK','OUTBOUND')), sample_status text NOT NULL CHECK(sample_status IN ('NOT_SAMPLED','SAMPLING','SAMPLED')), inbound_date date NOT NULL, inbound_at timestamptz NOT NULL, data_kind text NOT NULL CHECK(data_kind IN ('DEMO','REAL')), grade text NOT NULL DEFAULT '', purity text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,batch_id) REFERENCES batches(project_id,id), FOREIGN KEY(project_id,location_id) REFERENCES locations(project_id,id), FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id), FOREIGN KEY(project_id,reserved_for_customer_id) REFERENCES customers(project_id,id), CHECK(physical_status<>'OUTBOUND' OR reserved_for_customer_id IS NULL));
CREATE INDEX bundles_query_idx ON bundles(project_id,inbound_date,id);
CREATE INDEX bundles_customer_idx ON bundles(project_id,customer_id);
CREATE INDEX bundles_location_idx ON bundles(project_id,location_id);
CREATE INDEX bundles_batch_idx ON bundles(project_id,batch_id);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text, entity_id text, before_data jsonb, after_data jsonb, request_id text, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_demo_in_production() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.data_kind='DEMO' AND EXISTS(SELECT 1 FROM system_info WHERE environment='production') THEN RAISE EXCEPTION 'Demo inventory is forbidden in production'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bundles_data_boundary BEFORE INSERT OR UPDATE ON bundles FOR EACH ROW EXECUTE FUNCTION reject_demo_in_production();
CREATE VIEW inventory_view AS SELECT b.id AS uuid,b.bundle_no AS id,b.project_id,b.customer_id,l.warehouse_id,c.name AS customer,l.code AS location,t.code AS batch,b.net_weight AS weight,CASE WHEN b.physical_status='OUTBOUND' THEN '已出库' WHEN b.reserved_for_customer_id IS NOT NULL THEN '已预留' ELSE '在库' END AS status,CASE b.sample_status WHEN 'NOT_SAMPLED' THEN '未取样' WHEN 'SAMPLING' THEN '取样中' ELSE '已取样' END AS sample,to_char(b.inbound_date,'YYYY-MM-DD') AS date,b.grade,b.purity,b.data_kind,b.version FROM bundles b JOIN customers c ON c.id=b.customer_id JOIN locations l ON l.id=b.location_id JOIN batches t ON t.id=b.batch_id;
INSERT INTO roles VALUES ('admin','系统管理员'),('operator','现场操作员'),('supervisor','业务主管'),('sales','销售'),('readonly','只读管理人员');
INSERT INTO permissions VALUES ('inventory:read'),('inventory:export'),('users:manage'),('audit:read');
INSERT INTO role_permissions SELECT code,'inventory:read' FROM roles;
INSERT INTO role_permissions VALUES ('admin','inventory:export'),('admin','users:manage'),('admin','audit:read'),('supervisor','inventory:export'),('supervisor','audit:read'),('sales','inventory:export');
